// IronBrawlers.js
import React from "react";
import ContentPost from "../../ProjectComponents/components/ContentPost"; // Import the ContentPost component

export default function IronBrawlers() {
  return (
    <div className="container mx-auto px-5 py-10 lg:px-40">
      <h1 className="text-4xl font-bold text-white mb-8">Iron Brawlers</h1>

      {/* You can use the ContentPost component multiple times to build out the page */}
      <ContentPost
        title="Introduction"
        description="Iron Brawlers is an exciting multiplayer fighting game with unique characters and immersive environments."
        image="/Images/gamedev/Iron-Brawlers.gif"
      />

      {/* Add more ContentPost components as needed */}
    </div>
  );
}
